mapper.select:
SELECT COUNT(1) FROM TBL_COLLATERAL_INFO
WHERE COLLATERAL_NO = #{collateralNo}

    AND ID != #{excludeId}

SELECT
FROM TBL_COLLATERAL_INFO c LEFT JOIN TBL_COMPANY comp ON c.OWNER_ID = comp.ID AND c.OWNER_TYPE = 'COMPANY' LEFT JOIN TBL_STAFF staff ON c.OWNER_ID = staff.ID AND c.OWNER_TYPE = 'INDIVIDUAL' LEFT JOIN TBL_STAFF creator ON c.CREATED_BY = creator.ID LEFT JOIN ( SELECT COLLATERAL_ID, SUM(USAGE_AMOUNT) AS USED_AMOUNT FROM TBL_COLLATERAL_USAGE WHERE USAGE_STATUS = 'ACTIVE' GROUP BY COLLATERAL_ID ) usage ON c.ID = usage.COLLATERAL_ID WHERE c.OWNER_ID = #{ownerId}
AND c.OWNER_TYPE = #{ownerType}
ORDER BY c.CREATED_TIME DESC

SELECT
FROM TBL_COLLATERAL_INFO c LEFT JOIN TBL_COMPANY comp ON c.OWNER_ID = comp.ID AND c.OWNER_TYPE = 'COMPANY' LEFT JOIN TBL_STAFF staff ON c.OWNER_ID = staff.ID AND c.OWNER_TYPE = 'INDIVIDUAL' LEFT JOIN TBL_STAFF creator ON c.CREATED_BY = creator.ID LEFT JOIN ( SELECT COLLATERAL_ID, SUM(USAGE_AMOUNT) AS USED_AMOUNT FROM TBL_COLLATERAL_USAGE WHERE USAGE_STATUS = 'ACTIVE' GROUP BY COLLATERAL_ID ) usage ON c.ID = usage.COLLATERAL_ID WHERE c.COLLATERAL_STATUS = 'AVAILABLE'
AND c.OWNER_ID = #{ownerId}
AND c.CURRENT_VALUE >= #{minValue}
ORDER BY c.CURRENT_VALUE DESC
